using SimplePZMapmaker.Core;
using System.Text.Json;
public static class SourceTransferTests{
 public static IEnumerable<(string,Action)> Cases(){
  yield return("source audit rechecks mapped entrances after an authored wall edit",()=>{var p=SiteTests.Fixture();var b=p.Buildings[0];var floor=b.Design!.Floors[-b.Design.MinLevel];var edge=floor.Edges.First(e=>e.Kind=="wall"&&(BuildingDesigner.Cell(b,floor,e.X,e.Y)=='.')!=(BuildingDesigner.Cell(b,floor,e.X-(e.Edge=="w"?1:0),e.Y-(e.Edge=="n"?1:0))=='.'));var e=new GeographicFeature{Id="entrance",SourceId="osm-node-2",Kind="entrance",GeometryKind="point",BuildingId=b.Id,EntranceOutcome="mapped",Geometry=[[new(b.X+edge.X+(edge.Edge=="n"?.5:0),b.Y+edge.Y+(edge.Edge=="w"?.5:0))]],SourceGeometry=[[new(32,54)]]};p.SourceFeatures.Add(e);foreach(var v in floor.Edges.Where(v=>v.Kind=="door"))v.Kind="wall";Check(SourceTransferAudit.Analyze(p).Issues.Any(i=>i.Code=="source-entrance-drift"),"Removed source door still reported as mapped");});
  yield return("source audit detects authored displacement without mutating evidence",()=>{var p=SiteTests.Fixture();p.Buildings[0].X+=20;var before=JsonSerializer.Serialize(p);var r=SourceTransferAudit.Analyze(p);Check(r.Issues.Any(i=>i.Code=="source-footprint-drift"),"Drift hidden");Check(JsonSerializer.Serialize(p)==before,"Audit mutated map");});
  yield return("source audit reports missing buildings and unknown service coverage",()=>{var p=SiteTests.Fixture();p.Buildings=[];p.Sites=[];var r=SourceTransferAudit.Analyze(p);Check(r.Issues.Any(i=>i.Code=="source-building-missing"),"Missing source hidden");Check(r.Coverage.PoiCoverage=="unknown"&&!r.Issues.Any(i=>i.Code=="missing-school"),"Invented completeness");});
  yield return("source audit bounds selected evidence and qualifies straight line distances",()=>{var p=SiteTests.Fixture();var e=NeighborhoodPlanner.Copy(p.SourceFeatures[0]);e.Id="clinic";e.Kind="poi";e.Tags=new(){["amenity"]="clinic"};e.GeometryKind="point";e.Geometry=[[new(90,80)]];e.SourceGeometry=[[new(32,54)]];e.BuildingId=null;p.SourceFeatures.Add(e);var r=SourceTransferAudit.Analyze(p,maxFeatures:1);Check(!r.Complete&&r.Coverage.EvaluatedFeatures==1,"Cap hidden");r=SourceTransferAudit.Analyze(p);Check(r.Services.Single().RouteStatus=="not-computed"&&r.Services[0].StraightLineTiles>0,"Straight line mislabelled as route");});
 }
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
}
